    AutoPtr<ASTListType> listType = new ASTListType();
    listType->SetElementType(type);
    AutoPtr<ASTType> retType = ast_->FindType(listType->ToString(), false);
    if (retType == nullptr) {
        retType = listType.Get();
        ast_->AddType(retType);
    }
    return retType;
}

